// STUB generated by the coordinator: replace every not_implemented entry with a real,
// independent test. The runner receives the full CTest name as argv[1].
#include "setar/instrument/instrument.hpp"

#include <array>
#include <exception>
#include <iostream>
#include <stdexcept>
#include <string_view>

namespace {
void not_implemented() { throw std::runtime_error("test not implemented yet"); }
} // namespace

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: runner <ctest-name>\n";
        return 2;
    }
    const std::string_view requested(argv[1]);
    struct Case {
        std::string_view name;
        void (*run)();
    };
    const std::array<Case, 17> tests{{
        {"engine.config_validation", not_implemented},
        {"engine.lossless_energy_ledger", not_implemented},
        {"engine.lossy_energy_ledger", not_implemented},
        {"engine.open_string_pitch", not_implemented},
        {"engine.fretted_pitch", not_implemented},
        {"engine.event_ordering", not_implemented},
        {"engine.newton_failure_reporting", not_implemented},
        {"contact.nail_passivity", not_implemented},
        {"contact.release_convergence", not_implemented},
        {"contact.fret_crossing_work", not_implemented},
        {"contact.release_afterlength", not_implemented},
        {"coupling.cross_string_transfer", not_implemented},
        {"coupling.uncoupled_limit", not_implemented},
        {"performance.persistent_state", not_implemented},
        {"performance.restrike_memory", not_implemented},
        {"acoustics.observation_invariance", not_implemented},
        {"controls.sweep_continuity", not_implemented},
    }};
    try {
        for (const auto& test : tests) {
            if (test.name == requested) {
                test.run();
                std::cout << "PASS " << requested << '\n';
                return 0;
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "FAIL " << requested << ": " << e.what() << '\n';
        return 1;
    }
    std::cerr << "unknown test: " << requested << '\n';
    return 2;
}
